"""Install CI-only integration checks and stacked data-map fixture packs."""
import json
from pathlib import Path

Path("src/main/java/com/simibubi/create/infrastructure/fabric/IntegrationDataProbe.java").write_text("package com.simibubi.create.infrastructure.fabric;\n\nimport com.google.gson.JsonParser;\nimport com.mojang.serialization.JsonOps;\nimport com.simibubi.create.api.registry.CreateDataMaps;\nimport com.simibubi.create.content.fluids.transfer.FillingRecipe;\nimport com.simibubi.create.foundation.mixin.fabric.HoneycombDataMapAccessor;\nimport com.simibubi.create.infrastructure.fabric.transfer.fluid.FluidStack;\nimport net.fabricmc.fabric.api.registry.FuelRegistry;\nimport net.fabricmc.fabric.api.transfer.v1.fluid.FluidConstants;\nimport net.minecraft.core.registries.BuiltInRegistries;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.server.MinecraftServer;\nimport net.minecraft.world.item.Items;\nimport net.minecraft.world.level.block.Blocks;\nimport net.minecraft.world.level.block.WeatheringCopper;\n\npublic class IntegrationDataProbe {\n    private static void check(boolean result, String message) {\n        if (!result) throw new IllegalStateException(\"INTEGRATION_PROBE: \" + message);\n    }\n    public static void verify(MinecraftServer server) {\n        var pie = server.getRecipeManager().byKey(ResourceLocation.parse(\"farmersdelight:integration/create/filling/chocolate_pie\")).orElseThrow();\n        check(pie.value() instanceof FillingRecipe, \"chocolate pie is not a filling recipe\");\n        var filling = (FillingRecipe) pie.value();\n        check(filling.getIngredients().size() == 1 && filling.getFluidIngredients().size() == 1, \"pie ingredient classification\");\n        check(filling.getRequiredFluid().getRequiredAmount() == FluidConstants.BUCKET / 2, \"pie fluid amount\");\n        check(filling.getRequiredFluid().test(new FluidStack(BuiltInRegistries.FLUID.get(ResourceLocation.parse(\"create:chocolate\")), FluidConstants.BUCKET / 2)), \"pie rejects chocolate\");\n        check(CreateDataMaps.SUPERHEATED_BLAZE_BURNER_FUELS.get(BuiltInRegistries.ITEM.get(ResourceLocation.parse(\"create:blaze_cake\"))).burnTime() == 3200, \"default blaze cake\");\n        check(CreateDataMaps.REGULAR_BLAZE_BURNER_FUELS.get(Items.STICK).burnTime() == 123, \"pack priority\");\n        check(CreateDataMaps.REGULAR_BLAZE_BURNER_FUELS.get(Items.SPRUCE_LOG).burnTime() == 77, \"fuel tag\");\n        check(!CreateDataMaps.REGULAR_BLAZE_BURNER_FUELS.containsKey(Items.OAK_LOG), \"fuel removal\");\n        check(FuelRegistry.INSTANCE.get(Items.STICK) == 1234, \"furnace data map not applied\");\n        int oxidation = 0, waxing = 0;\n        for (var block : BuiltInRegistries.BLOCK) {\n            var id = BuiltInRegistries.BLOCK.getKey(block);\n            if (!id.getNamespace().equals(\"create\")) continue;\n            if (WeatheringCopper.getNext(block).isPresent()) {\n                var next = WeatheringCopper.getNext(block).orElseThrow();\n                check(WeatheringCopper.getPrevious(next).orElseThrow() == block, \"oxidation reverse\");\n                oxidation++;\n            }\n            if (HoneycombDataMapAccessor.create$getWaxablesSupplier().get().containsKey(block)) waxing++;\n        }\n        check(oxidation == 18 && waxing == 24, \"Create copper maps not applied: \" + oxidation + \"/\" + waxing);\n        check(WeatheringCopper.getNext(Blocks.COPPER_BLOCK).orElseThrow() == Blocks.EXPOSED_COPPER, \"vanilla oxidation lost\");\n        check(WeatheringCopper.getNext(Blocks.STONE).isEmpty(), \"copper removal\");\n        System.out.println(\"INTEGRATION_PROBE passed: chocolate pie, stacked/tagged/removed fuel maps, furnace fuel, 18 oxidation and 24 waxing pairs\");\n    }\n}\n")
probe = Path("src/main/java/com/simibubi/create/infrastructure/fabric/PotionRecipeProbe.java")
probe.write_text(probe.read_text().replace("var level = server.overworld();", "IntegrationDataProbe.verify(server);\n            var level = server.overworld();"))
def write(pack, path, value):
    target = Path("run/server/world/datapacks") / pack / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(value))
for pack in ["probe_low", "probe_high"]:
    write(pack, "pack.mcmeta", {"pack": {"pack_format": 48, "description": "CI data map fixture"}})
write("probe_low", "data/create/data_maps/item/regular_blaze_burner_fuels.json", {"values": {"#minecraft:logs": {"burn_time": 77}, "minecraft:stick": {"burn_time": 88}}})
write("probe_high", "data/create/data_maps/item/regular_blaze_burner_fuels.json", {"values": {"minecraft:stick": {"burn_time": 123}}, "remove": ["minecraft:oak_log"]})
write("probe_high", "data/neoforge/data_maps/item/furnace_fuels.json", {"values": {"minecraft:stick": {"burn_time": 1234}}})
write("probe_low", "data/neoforge/data_maps/block/oxidizables.json", {"values": {"minecraft:stone": {"next_oxidation_stage": "minecraft:cobblestone"}}})
write("probe_high", "data/neoforge/data_maps/block/oxidizables.json", {"values": {}, "remove": ["minecraft:stone"]})

build = Path("build.gradle.kts")
build.write_text(build.read_text() + '\ndependencies { modLocalRuntime("maven.modrinth:farmers-delight-refabricated:$farmersDelightVersion") }\n')
